"use client";
import { useState, useEffect } from "react";
import { motion, AnimatePresence } from "framer-motion";
import GameBoard from "../components/GameBoard";

export type TemaBaralho = { id: string; nome: string; tipo: string; cor: string; destaque: string; escudo: string; sigla: string; };

// LISTA RESUMIDA PARA O CÓDIGO AQUI (MANTENHA OS 48 TIMES QUE VOCÊ JÁ TEM)
const BARALHOS: TemaBaralho[] = [
  { id: "gen-dark", nome: "Midnight Blue", tipo: "Clássico", cor: "bg-slate-900", destaque: "text-slate-400", escudo: "", sigla: "♠" },
  { id: "br-bfr", nome: "Botafogo", tipo: "Série A", cor: "bg-[repeating-linear-gradient(90deg,#111_0px,#111_20px,#fff_20px,#fff_40px)]", destaque: "text-gray-400", escudo: "/escudos/botafogo.e439f7a4.png", sigla: "BFR" },
  { id: "br-fla", nome: "Flamengo", tipo: "Série A", cor: "bg-[repeating-linear-gradient(0deg,#b91c1c_0px,#b91c1c_20px,#111_20px,#111_40px)]", destaque: "text-red-500", escudo: "/escudos/flamengo.9c3055f2.png", sigla: "CRF" },
  // ... coloque seus 48 baralhos originais aqui ...
];

const CATEGORIAS_SALAS = [
  { id: "SALA-INICIANTE", nome: "Iniciante", buyIn: 25, icone: "🥉", pot: 100, cor: "from-amber-700 to-amber-900" },
  { id: "SALA-INTERMEDIARIO", nome: "Intermediário", buyIn: 50, icone: "🥈", pot: 200, cor: "from-slate-400 to-slate-600" },
  { id: "SALA-PRO", nome: "Profissional", buyIn: 100, icone: "🥇", pot: 400, cor: "from-yellow-400 to-amber-600" }
];

const validarCPF = (cpf: string) => { cpf = cpf.replace(/[^\d]+/g, ""); if (cpf.length !== 11) return false; return true; };
const maskCPF = (value: string) => value.replace(/\D/g, "").replace(/(\d{3})(\d)/, "$1.$2").replace(/(\d{3})(\d)/, "$1.$2").replace(/(\d{3})(\d{1,2})/, "$1-$2").replace(/(-\d{2})\d+?$/, "$1");
const maskData = (value: string) => value.replace(/\D/g, "").replace(/(\d{2})(\d)/, "$1/$2").replace(/(\d{2})(\d)/, "$1/$2").replace(/(\d{4})\d+?$/, "$1");

export default function Home() {
  const [usuarioLogado, setUsuarioLogado] = useState<{ id: string; nome: string; usuario: string; moedas: number } | null>(null);
  const [isLogin, setIsLogin] = useState(true);
  const [erroAuth, setErroAuth] = useState("");
  const [loading, setLoading] = useState(false);
  const [bonusAlerta, setBonusAlerta] = useState(false);

  const [form, setForm] = useState({ nome: "", cpf: "", dataNascimento: "", email: "", usuario: "", senha: "" });

  const [salaDaPartida, setSalaDaPartida] = useState("");
  const [buyInPartida, setBuyInPartida] = useState(0);
  const [temaIndex, setTemaIndex] = useState(0);
  const [jogando, setJogando] = useState(false);

  const temaSelecionado = BARALHOS[temaIndex];

  useEffect(() => {
    const salvo = localStorage.getItem("@suecabet:user");
    if (salvo) setUsuarioLogado(JSON.parse(salvo));
  }, []);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setErroAuth("");
    setLoading(true);

    if (!isLogin && !validarCPF(form.cpf)) {
      setErroAuth("CPF inválido."); setLoading(false); return;
    }

    try {
      const res = await fetch(`http://localhost:3001/api/${isLogin ? 'login' : 'register'}`, {
        method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(form),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error);

      localStorage.setItem("@suecabet:user", JSON.stringify(data.user));
      setUsuarioLogado(data.user);
      if (data.bonusRecebido) {
        setBonusAlerta(true);
        setTimeout(() => setBonusAlerta(false), 5000);
      }
    } catch (err: any) { setErroAuth(err.message); }
    setLoading(false);
  };

  const resgatarEmergencia = async () => {
    try {
      const res = await fetch(`http://localhost:3001/api/resgate`, {
        method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ userId: usuarioLogado?.id })
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error);
      
      const atualizado = { ...usuarioLogado!, moedas: data.moedas };
      setUsuarioLogado(atualizado);
      localStorage.setItem("@suecabet:user", JSON.stringify(atualizado));
      alert("Resgate de 50 moedas efetuado com sucesso!");
    } catch (e: any) { alert(e.message); }
  };

  const iniciarJogo = (salaId: string, buyIn: number) => {
    if (usuarioLogado && usuarioLogado.moedas < buyIn && salaId !== "TREINO-LOCAL") {
      alert(`Saldo insuficiente! Você precisa de ${buyIn} SuecaCoins.`);
      return;
    }
    setSalaDaPartida(salaId);
    setBuyInPartida(buyIn);
    setJogando(true);
  };

  if (jogando && usuarioLogado) {
    return (
      <div className="w-screen h-screen bg-[#0b1510] overflow-hidden">
        <GameBoard salaId={salaDaPartida} tema={temaSelecionado} nomeJogador={usuarioLogado.nome} userId={usuarioLogado.id} buyIn={buyInPartida} />
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-[#050a07] text-white flex items-center justify-center relative overflow-hidden font-sans p-4">
      {/* Background idêntico mantido */}
      <AnimatePresence mode="wait">
        {bonusAlerta && (
          <motion.div initial={{ y: -50, opacity: 0 }} animate={{ y: 20, opacity: 1 }} exit={{ opacity: 0 }} className="fixed top-0 z-50 bg-emerald-500 text-black font-bold px-6 py-3 rounded-full shadow-lg">
            🎉 Bônus Diário Recebido: +25 SuecaCoins!
          </motion.div>
        )}
      </AnimatePresence>

      <AnimatePresence mode="wait">
        {!usuarioLogado ? (
          <motion.div key="auth" className="relative z-10 w-full max-w-md bg-gradient-to-br from-black/60 via-black/50 to-black/70 backdrop-blur-3xl border border-emerald-500/40 p-8 rounded-[2.5rem]">
             {/* Formulário de Login/Registro idêntico ao que você já possui */}
             <h1 className="text-4xl font-black text-center text-white tracking-widest mb-2">SUECA<span className="text-emerald-500">bet</span></h1>
             <form onSubmit={handleAuth} className="flex flex-col gap-4 mt-6">
                {!isLogin && <input type="text" placeholder="Nome Completo" required value={form.nome} onChange={e=>setForm({...form,nome:e.target.value})} className="bg-black/50 border border-white/10 rounded-xl px-4 py-3 outline-none focus:border-emerald-500" />}
                {!isLogin && <input type="text" placeholder="CPF" required value={form.cpf} onChange={e=>setForm({...form,cpf:maskCPF(e.target.value)})} className="bg-black/50 border border-white/10 rounded-xl px-4 py-3 outline-none focus:border-emerald-500" />}
                {!isLogin && <input type="email" placeholder="E-mail" required value={form.email} onChange={e=>setForm({...form,email:e.target.value})} className="bg-black/50 border border-white/10 rounded-xl px-4 py-3 outline-none focus:border-emerald-500" />}
                <input type="text" placeholder="Usuário" required value={form.usuario} onChange={e=>setForm({...form,usuario:e.target.value})} className="bg-black/50 border border-white/10 rounded-xl px-4 py-3 outline-none focus:border-emerald-500" />
                <input type="password" placeholder="Senha" required value={form.senha} onChange={e=>setForm({...form,senha:e.target.value})} className="bg-black/50 border border-white/10 rounded-xl px-4 py-3 outline-none focus:border-emerald-500" />
                {erroAuth && <p className="text-rose-400 text-xs text-center font-bold">{erroAuth}</p>}
                <button type="submit" disabled={loading} className="w-full bg-emerald-500 text-black font-black py-4 rounded-xl mt-4 hover:scale-[1.02]">{isLogin ? "ENTRAR" : "CRIAR CONTA"}</button>
             </form>
             <button onClick={()=>setIsLogin(!isLogin)} className="w-full text-center text-xs text-white/40 mt-6">{isLogin ? "Cadastre-se" : "Faça login"}</button>
          </motion.div>
        ) : (
          <motion.div key="lobby" className="relative z-10 w-full max-w-6xl mx-auto flex flex-col md:flex-row items-center justify-between gap-12 px-6">
            
            {/* Header VIP */}
            <div className="absolute -top-15 right-0 flex items-center gap-4">
              {usuarioLogado.moedas === 0 && (
                <button onClick={resgatarEmergencia} className="animate-pulse bg-rose-600 hover:bg-rose-500 text-white text-xs font-bold px-4 py-2 rounded-full shadow-[0_0_15px_rgba(225,29,72,0.5)]">
                  🆘 Resgate 50 Moedas
                </button>
              )}
              <div className="px-5 py-2 bg-gradient-to-r from-yellow-500/20 to-amber-600/20 border border-yellow-500/40 rounded-full flex items-center gap-2">
                <span className="text-yellow-400 font-black text-lg drop-shadow-md">💰 {Math.floor(usuarioLogado.moedas)}</span>
                <span className="text-white/60 text-xs font-medium uppercase tracking-widest">SuecaCoins</span>
              </div>
              <button onClick={() => { localStorage.removeItem("@suecabet:user"); setUsuarioLogado(null); }} className="text-white/30 hover:text-rose-400 text-xs font-bold uppercase border border-white/10 px-4 py-1.5 rounded-full">Sair</button>
            </div>

            <div className="flex-1 flex flex-col items-start w-full">
              <h1 className="text-6xl sm:text-7xl font-black text-white tracking-tighter mb-8 relative">SUECA<span className="text-emerald-500">bet</span></h1>

              <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 w-full">
                {CATEGORIAS_SALAS.map(sala => (
                  <button key={sala.id} onClick={() => iniciarJogo(sala.id, sala.buyIn)} className={`relative group overflow-hidden bg-black/40 border border-white/10 p-6 rounded-[2rem] flex flex-col items-center hover:-translate-y-2 transition-all shadow-lg hover:shadow-[0_0_30px_rgba(255,255,255,0.1)]`}>
                    <div className={`absolute inset-0 bg-gradient-to-b ${sala.cor} opacity-10 group-hover:opacity-30 transition-opacity`}></div>
                    <span className="text-5xl mb-3 relative z-10">{sala.icone}</span>
                    <h3 className="text-white font-black text-xl mb-1 relative z-10 uppercase tracking-wider">{sala.nome}</h3>
                    <div className="flex items-center gap-1 bg-black/50 px-3 py-1 rounded-full mb-4 relative z-10 border border-white/5">
                      <span className="text-[10px] text-white/50 uppercase tracking-widest font-bold">Buy-in:</span>
                      <span className="text-yellow-400 font-bold text-sm">💰 {sala.buyIn}</span>
                    </div>
                    <p className="text-emerald-400/80 text-xs font-bold uppercase tracking-widest relative z-10">Pote: {sala.pot} SC</p>
                  </button>
                ))}
              </div>
              <button onClick={() => iniciarJogo("TREINO-LOCAL", 0)} className="mt-6 text-white/40 text-xs font-bold uppercase tracking-widest hover:text-emerald-400 transition-colors flex items-center gap-2"><span>🤖</span> Treinar Offline (Grátis)</button>
            </div>

            {/* Carrossel de Baralho idêntico ao que você tem */}
            <div className="w-full md:w-[400px] flex flex-col items-center">
              <div className="bg-[#0b1510]/80 backdrop-blur-xl border border-white/5 p-8 rounded-[2.5rem] w-full flex flex-col items-center shadow-2xl">
                <span className="text-[9px] text-white/30 uppercase tracking-[0.3em] font-bold mb-8">Design do Baralho</span>
                <AnimatePresence mode="wait">
                  <motion.div key={temaSelecionado.id} className={`relative w-40 h-56 rounded-[1.25rem] border border-white/20 bg-cover bg-center flex items-center justify-center ${temaSelecionado.cor}`}>
                    {temaSelecionado.escudo ? <img src={temaSelecionado.escudo} className="w-20 h-20 object-contain drop-shadow-2xl z-10" /> : <span className="text-5xl text-white/50 z-10">{temaSelecionado.sigla}</span>}
                  </motion.div>
                </AnimatePresence>
                <div className="flex items-center justify-between w-full mt-10 px-2">
                  <button onClick={prevTema} className="w-12 h-12 rounded-full bg-white/5 text-white/40">&lt;</button>
                  <div className="text-center px-4 w-48"><p className="font-bold text-white text-lg">{temaSelecionado.nome}</p></div>
                  <button onClick={nextTema} className="w-12 h-12 rounded-full bg-white/5 text-white/40">&gt;</button>
                </div>
              </div>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </div>
  );
}